from lib import *
S = SS('w14')
steps = [
    step("ping 一次,线上是两个 ICMP 包。在 lo0 上 ping 127.0.0.1 和在 en0 上 ping 默认网关,结构完全一样:请求 ICMP 类型 8 代码 0,应答类型 0 代码 0;IP 总长都是 84 字节(20 字节 IP 头 + 8 字节 ICMP 头 + 56 字节载荷),TTL 64;应答的标识符、序号、载荷与请求逐字节相同。标识符每次运行不同(这两次分别是 0x441a、0x481a),序号从 0 开始。载荷的前 8 字节是发送时间(秒 + 微秒),与抓包时间戳只差 25 µs(lo0)和 215 µs(en0);后 48 字节是从 0x08 开始逐字节加 1 的图案。所以 ping 收到应答后,直接从应答载荷里取出发送时间就能算 RTT,不需要自己再存一份。", t=tl(S(1)), mark=lidx(S(1), '请求:IP 总长', '应答:IP 总长'), done=lidx(S(1), '请求的载荷前 8 字节', '应答的标识符'), kv=KV([['请求 / 应答', '类型 8 / 0,代码 0'], ['IP 总长', '84 = 20 + 8 + 56'], ['载荷前 8 字节', '发送时间戳(秒 + 微秒)'], ['载荷后 48 字节', '0x08 起递增的图案'], ['应答', '标识符、序号、载荷原样回送']], ['载荷前 8 字节'])),
    step("ICMP 校验和只覆盖 ICMP 报文(头 + 载荷,不含 IP 头):字段先填 0,按 16 位字求和、进位折回、取反。自己算的结果和抓到的值在四个包上全部一致(lo0 请求 0x618a、应答 0x698a;en0 请求 0x1070、应答 0x1870);把整个报文连校验和一起再求一次和,结果是 0x0000,这就是接收方的检验办法。请求和应答的校验和相差 0x0800,因为类型字段的高字节从 8 变成 0。", t=tl(S(2)), mark=lidx(S(2), 'lo0 请求', 'lo0 应答', 'en0 请求', 'en0 应答'), done=lidx(S(2), '规则'), kv=KV([['范围', 'ICMP 头 + 载荷,不含 IP 头'], ['算法', '16 位字求和,进位折回,取反'], ['验证', '含校验和再求和 = 0x0000'], ['请求 vs 应答', '只差 0x0800']], ['验证'])),
    step("RTT 从哪来:对默认网关连发 30 个 ping(间隔 0.2 s),全部收到。ping 报告的 RTT 最小 2.613、中位 2.958、最大 35.607 ms;抓包里请求到应答的时间差最小 2.364、中位 2.751、最大 35.458 ms。逐个对比 30 个,ping 报的总是比抓包多 0.084~0.534 ms(中位 0.194)——ping 的计时包含了从发出前到读到应答之间在本机里多花的时间。最快的 3 个在 2.6 ms 附近,最慢的 3 个是 25.177、29.527、35.607 ms:Wi-Fi 链路的偶发延迟远大于典型值。127.0.0.1 的 RTT 中位只有 0.132 ms(抓包 0.043 ms),网关的中位是它的 22 倍。", t=tl(S(3)), mark=lidx(S(3), '最慢的 3 个', '网关的 RTT 中位'), done=lidx(S(3), '默认网关:发 30 个', '抓包得到的 RTT', '逐个对比', '127.0.0.1:收到'), b=bars([['网关 · ping 报告 中位', 2.958, '2.958 ms'], ['网关 · 抓包 中位', 2.751, '2.751 ms'], ['127.0.0.1 · ping 报告 中位', 0.132, '0.132 ms'], ['127.0.0.1 · 抓包 中位', 0.043, '0.043 ms']], 3, mark=[0], done=[1, 2, 3]), kv=KV([['ping 的 time', '比抓包多 0.084~0.534 ms'], ['网关 RTT', '中位 2.958 ms,最大 35.607 ms'], ['127.0.0.1', '中位 0.132 ms'], ['波动', 'Wi-Fi 上偶发的几十 ms']], ['ping 的 time'])),
    step("载荷大小对 RTT 的影响:对默认网关用 -s 指定 0 / 56 / 512 / 1472 / 4000 字节各 15 个,都全部收到。第一个包的 IP 总长是 28 / 84 / 540 / 1500 / 1500;载荷 4000 字节时请求和应答各被分成 3 片,抓到 90 个 IP 包(15 个来回 × 6 片),全部是分片。载荷为 0 时不到 8 字节,放不下时间戳,ping 一个 time= 也打印不出来(15 个都没有),RTT 只能靠抓包得到。抓包 RTT 的最小值 2.348 / 2.256 / 2.397 / 2.496 / 2.963 ms,中位 4.087 / 3.623 / 2.850 / 2.867 / 3.395 ms——每组只有 15 个样本,Wi-Fi 的抖动比包大小的影响大,中位数甚至不单调,这个实验不能量化“每字节多少时间”。", t=tl(S(4)), mark=lidx(S(4), '载荷    0 字节', '载荷 4000 字节', '抓包 RTT 中位的变化'), done=lidx(S(4), '载荷   56 字节', '载荷  512 字节', '载荷 1472 字节'), b=bars([['载荷 0 · 最小 RTT', 2.348, '2.348 ms'], ['载荷 56', 2.256, '2.256 ms'], ['载荷 512', 2.397, '2.397 ms'], ['载荷 1472', 2.496, '2.496 ms'], ['载荷 4000(3 片)', 2.963, '2.963 ms']], 3, mark=[4], done=[0, 1, 2, 3]), kv=KV([['载荷 0', '放不下时间戳,ping 不显示 time'], ['载荷 4000', '请求、应答各 3 片,共 90 个包'], ['结论', '15 个样本的抖动大于大小的影响']], ['载荷 0'])),
    step("不用 root 自己发 echo:macOS 允许 SOCK_DGRAM + IPPROTO_ICMP 套接字,自己填类型、标识符、序号、载荷和校验和。我填标识符 0x1234、序号 7、34 字节载荷,线上发出的请求这三项都原样保留(标识符没有被内核改写),应答的标识符、序号、载荷也相同。recvfrom 拿到 62 字节:开头是 20 字节 IP 头(0x45),后面才是 ICMP 类型 0 代码 0;应用层测得 RTT 3.269 ms。另开一个从没发过包的 ICMP 套接字 s2,s 再发一次请求时,s2 也收到了一个 62 字节的应答(类型 0、标识符 0x1234、序号 7)——这里只观察到现象,内核的分发规则没有进一步验证。", t=tl(S(5)), mark=lidx(S(5), '线上发出的请求', 'recvfrom 拿到', '同时开着另一个'), done=lidx(S(5), '我填的', '线上收到的应答', '应用里收到'), kv=KV([['套接字', 'SOCK_DGRAM + IPPROTO_ICMP,不需要 root'], ['标识符 / 序号', '线上原样保留'], ['recvfrom', '带 20 字节 IP 头'], ['另一个 ICMP 套接字', '也收到了这个应答']], ['recvfrom'])),
]
A = mkartw('w14', 14, '网络协议,ICMP,echo,ping,RTT,校验和,真实验证,动画演示',
    '抓包看 ping:类型 8/0、84 字节的 IP 包、载荷前 8 字节是发送时间戳;ICMP 校验和手算与抓包一致;ping 报的 RTT 比抓包多 0.08~0.5 ms;4000 字节载荷被分成 3 片;用非特权 ICMP 套接字自己发 echo。',
    'ping 一次到底发了什么?RTT 是从哪里量出来的?-s 改了载荷大小以后线上有什么变化?这篇在 lo0 和 en0 上抓 ICMP echo 的请求与应答,手算校验和,对比 ping 报的时间和抓包的时间,再用不需要 root 的 ICMP 套接字自己发一个 echo。',
    [('84 字节', 'ping 默认的 IP 包大小:20 字节 IP 头 + 8 字节 ICMP 头 + 56 字节载荷'), ('0.084~0.534 ms', 'ping 报告的 RTT 比抓包里请求到应答的时间差多出的部分(30 个逐个对比)'), ('4000 → 90 个包', '载荷 4000 字节的 15 个 ping,请求和应答各分成 3 片')],
    [('echo 请求与应答', '<p>类型 8 是请求、0 是应答,代码都是 0;标识符、序号、载荷在应答里原样回送。ping 把发送时间放在载荷前 8 字节里,收到应答后直接取出来算 RTT。</p>'),
     ('校验和', '<p>只覆盖 ICMP 报文,不含 IP 头。自己算的值和 lo0、en0 上四个包完全一致;含校验和再求一次和等于 0。</p>'),
     ('RTT', '<p>局域网网关的 RTT 中位约 3 ms,127.0.0.1 约 0.13 ms。ping 报告的时间总比抓包多一点本机内部的耗时;Wi-Fi 上偶尔出现几十毫秒的尖峰。</p>'),
     ('载荷大小', '<p>载荷小于 8 字节放不下时间戳,ping 不显示 time。载荷超过 MTU 时请求和应答都会分片。15 个样本的实验里 RTT 受抖动影响比受大小影响大。</p>'),
     ('非特权 ICMP 套接字', '<p>macOS 允许普通用户用 SOCK_DGRAM + IPPROTO_ICMP 发 echo,标识符、序号和载荷原样上线;recvfrom 收到的数据带 IP 头。</p>')],
    steps,
    [ENV_W + '。第一、二、五节在 lo0 与 en0 上抓包(用 dpkt 解析),默认网关地址与 MAC 做了遮盖;第三、四节 ping 间隔 0.2 s,网关是同一 Wi-Fi 网络里的路由器,RTT 数字随当时的无线环境变化,只看量级与相对关系',
     '没有验证:ICMP 其它类型(时间戳 13/14、地址掩码请求等,见后面的差错报文一篇);内核如何把应答分发给不同 ICMP 套接字;ping 以外工具(如 fping)的计时方式;更大样本下载荷大小与 RTT 的定量关系;公网 ICMP echo(本机的网络挡住了对外的 ping)'],
    'ICMP echo')
